/* Original small BASIC interpreter. Unsupported syntax reports a line error. */
#include "basic.h"
#include "netlib.h"
typedef struct {Basic *b;const BasicHost *host;const char *p;int depth;} Parser;
static char lower(char c){return c>='A'&&c<='Z'?c+32:c;}
int BasicEqual(const char *a,const char *b){while(*a&&lower(*a)==lower(*b)){a++;b++;}return *a==*b;}
static int namechar(char c){return (lower(c)>='a'&&lower(c)<='z')||(c>='0'&&c<='9')||c=='_'||c=='.';}
static void spaces(Parser *p){while(*p->p==' '||*p->p=='\t')p->p++;}
static int word(Parser *p,const char *text){spaces(p);const char *s=p->p;while(*text&&lower(*s)==lower(*text)){s++;text++;}if(*text||namechar(*s))return 0;p->p=s;return 1;}
static int identifier(Parser *p,char *out){spaces(p);if(!(lower(*p->p)>='a'&&lower(*p->p)<='z')&&*p->p!='_')return 0;int n=0;while(namechar(*p->p)){if(n>=31)return 0;out[n++]=*p->p++;}out[n]=0;return 1;}
static void fail(Parser *p,const char *text){if(!p->b->error[0]){copy(p->b->error,text);p->b->error_line=p->b->pc+1;}p->b->running=0;}
void BasicString(BasicValue *v,const char *s){memset(v,0,sizeof(*v));v->string=1;u32 n=strlen(s);if(n>127)n=127;memcpy(v->text,s,n);}
void BasicText(const BasicValue *v,char *out){if(v->string){copy(out,v->text);return;}u32 n=(u32)v->number;if(v->number<0){*out++='-';n=0u-n;}number(n,out);}
static int variable(Basic *b,const char *name,int create){for(int i=0;i<b->variables;i++)if(BasicEqual(b->variable[i].name,name))return i;if(!create||b->variables==BASIC_VARS)return -1;int i=b->variables++;copy(b->variable[i].name,name);return i;}
static i32 numeric(Parser *p,const BasicValue *v){if(!v->string)return v->number;const char *s=v->text;int sign=1;if(*s=='-'){sign=-1;s++;}i32 n=0;if(!*s){fail(p,"Expected a number");return 0;}while(*s){if(*s<'0'||*s>'9'||__builtin_mul_overflow(n,10,&n)||__builtin_add_overflow(n,*s++-'0',&n)){fail(p,"Invalid or overflowing numeric conversion");return 0;}}return sign*n;}
static BasicValue expression(Parser *,int);
static BasicValue builtin(Parser *p,const char *name){BasicValue args[3],v={0};int count=0;spaces(p);p->p++;spaces(p);if(*p->p!=')')for(;;){if(count==3){fail(p,"At most three arguments");return v;}args[count++]=expression(p,1);spaces(p);if(*p->p!=',')break;p->p++;}if(*p->p!=')'){fail(p,"Expected closing parenthesis");return v;}p->p++;
 if((BasicEqual(name,"CStr")||BasicEqual(name,"Str"))&&count==1){v.string=1;BasicText(&args[0],v.text);return v;}if((BasicEqual(name,"Val")||BasicEqual(name,"CInt")||BasicEqual(name,"CLng"))&&count==1){v.number=numeric(p,&args[0]);if(BasicEqual(name,"CInt")&&(v.number< -32768||v.number>32767))fail(p,"Integer overflow");return v;}
 if(BasicEqual(name,"Len")&&count==1){char s[128];BasicText(&args[0],s);v.number=(i32)strlen(s);return v;}
 if((BasicEqual(name,"Left")||BasicEqual(name,"Right")||BasicEqual(name,"Mid"))&&count>=2){char s[128];BasicText(&args[0],s);i32 n=(i32)strlen(s),a=numeric(p,&args[1]),start=0,bytes=a;if(BasicEqual(name,"Right"))start=n-a;if(BasicEqual(name,"Mid")){start=a-1;bytes=count==3?numeric(p,&args[2]):n-start;}if(start<0||start>n||bytes<0){fail(p,"String index out of range");return v;}if(bytes>n-start)bytes=n-start;v.string=1;memcpy(v.text,s+start,(u32)bytes);return v;}
 if((BasicEqual(name,"MsgBox")||BasicEqual(name,"InputBox"))&&count==1){char prompt[128];BasicText(&args[0],prompt);int input=BasicEqual(name,"InputBox");v.string=input;if(p->host->dialog)v.number=p->host->dialog(prompt,v.text,input);return v;}
 if(BasicEqual(name,"ReadFile")&&count==1){char path[128];BasicText(&args[0],path);int n=Read(path,v.text,127);if(n<0)fail(p,"File read failed (maximum 127 bytes)");else{v.string=1;v.text[n]=0;}return v;}
 if(BasicEqual(name,"ConfigRead")&&count==1){char path[128];copy(path,"/home/user/.sino/config/");char key[128];BasicText(&args[0],key);u32 n=strlen(key);if(!n||n>24){fail(p,"Configuration key too long");return v;}for(u32 i=0;i<n;i++)if(!namechar(key[i])||key[i]=='.'){fail(p,"Invalid config key");return v;}copy(path+strlen(path),key);int bytes=Read(path,v.text,127);if(bytes<0)fail(p,"Configuration read failed");else{v.string=1;v.text[bytes]=0;}return v;}
 if(BasicEqual(name,"HttpGet")&&count==2){char path[128],http[512];BasicText(&args[1],path);int n=HttpGet((u16)numeric(p,&args[0]),path,http,sizeof(http));if(n<0)fail(p,"HTTP denied or failed");else BasicString(&v,http);return v;}
 if(BasicEqual(name,"TcpConnect")&&count==1){int fd=socket(NET_TCP),r=fd;u32 start=Tick();if(fd>=0){while((r=connect(fd,(u16)numeric(p,&args[0])))==S_AGAIN&&Tick()-start<300)Yield(1);if(r<0){Close(fd);fd=r;}}v.number=fd;return v;}
 if(BasicEqual(name,"TcpSend")&&count==2){char data[128];BasicText(&args[1],data);v.number=send(numeric(p,&args[0]),data,strlen(data));return v;}
 if(BasicEqual(name,"TcpRecv")&&count==1){int n=recv(numeric(p,&args[0]),v.text,127);if(n<0)fail(p,"TCP read denied or not ready");else{v.string=1;v.text[n]=0;}return v;}
 fail(p,"Unknown function or wrong argument count");return v;}
static BasicValue atom(Parser *p){BasicValue v={0};spaces(p);if(++p->depth>12){fail(p,"Expression nesting limit");p->depth--;return v;}if(*p->p=='"'){p->p++;int n=0;while(*p->p&&*p->p!='"'){if(n>=127){fail(p,"String limit 127 bytes");break;}v.text[n++]=*p->p++;}if(*p->p!='"')fail(p,"Unterminated string");else p->p++;v.string=1;}
 else if(*p->p=='('){p->p++;v=expression(p,1);spaces(p);if(*p->p==')')p->p++;else fail(p,"Expected closing parenthesis");}
 else if(*p->p=='-'){p->p++;v=atom(p);i32 n=numeric(p,&v);v.string=0;if(__builtin_sub_overflow(0,n,&v.number))fail(p,"Numeric overflow");}
 else if(word(p,"Not")){v=atom(p);v.number=numeric(p,&v)?0:-1;v.string=0;}
 else if(*p->p>='0'&&*p->p<='9'){while(*p->p>='0'&&*p->p<='9')if(__builtin_mul_overflow(v.number,10,&v.number)||__builtin_add_overflow(v.number,*p->p++-'0',&v.number)){fail(p,"Numeric overflow");break;}}
 else{char name[32];if(!identifier(p,name))fail(p,"Expected expression");else if(BasicEqual(name,"True"))v.number=-1;else if(BasicEqual(name,"False"))v.number=0;else{spaces(p);int i=variable(p->b,name,0);if(*p->p=='('&&i>=0&&p->b->variable[i].array_size){p->p++;BasicValue index=expression(p,1);i32 n=numeric(p,&index);spaces(p);if(*p->p!=')'||n<0||n>=p->b->variable[i].array_size)fail(p,"Array index out of range");else{p->p++;v.number=p->b->variable[i].array[n];}}else if(*p->p=='(')v=builtin(p,name);else if(i>=0)v=p->b->variable[i].value;else if(!p->host->get||p->host->get(name,&v)<0)fail(p,"Unknown variable or property");}}
 p->depth--;return v;}
static int op(Parser *p,int *prec){spaces(p);const char *s=p->p;int code=0,n=1;*prec=3;if(s[0]=='<'&&s[1]=='>'){code=257;n=2;}else if(s[0]=='<'&&s[1]=='='){code=258;n=2;}else if(s[0]=='>'&&s[1]=='='){code=259;n=2;}else if(*s=='='||*s=='<'||*s=='>')code=*s;else if(*s=='+'||*s=='-'||*s=='&'){code=*s;*prec=4;}else if(*s=='*'||*s=='/'){code=*s;*prec=5;}else if(word(p,"Mod")){*prec=5;return 260;}else if(word(p,"And")){*prec=2;return 261;}else if(word(p,"Or")){*prec=1;return 262;}else if(word(p,"Xor")){*prec=1;return 263;}if(code)p->p+=n;return code;}
static BasicValue expression(Parser *p,int minimum){BasicValue a=atom(p);while(!p->b->error[0]){const char *saved=p->p;int prec,code=op(p,&prec);if(!code||prec<minimum){p->p=saved;break;}BasicValue b=expression(p,prec+1);if((code=='+'&&(a.string||b.string))||code=='&'){char x[128],y[128];BasicText(&a,x);BasicText(&b,y);if(strlen(x)+strlen(y)>127){fail(p,"String concatenation overflow");break;}BasicString(&a,x);copy(a.text+strlen(a.text),y);continue;}if(prec==3&&(a.string||b.string)){char x[128],y[128];BasicText(&a,x);BasicText(&b,y);int cmp=0;for(u32 i=0;x[i]||y[i];i++)if(x[i]!=y[i]){cmp=(u8)x[i]>(u8)y[i]?1:-1;break;}a.string=0;a.number=code=='='?cmp==0:code==257?cmp!=0:code=='<'?cmp<0:code=='>'?cmp>0:code==258?cmp<=0:cmp>=0;a.number=a.number?-1:0;continue;}
 i32 x=numeric(p,&a),y=numeric(p,&b),z=0;a.string=0;if(code=='+'&&__builtin_add_overflow(x,y,&z))fail(p,"Addition overflow");else if(code=='-'&&__builtin_sub_overflow(x,y,&z))fail(p,"Subtraction overflow");else if(code=='*'&&__builtin_mul_overflow(x,y,&z))fail(p,"Multiplication overflow");else if(code=='/'||code==260){if(!y||((u32)x==0x80000000u&&y==-1))fail(p,"Division by zero or overflow");else z=code=='/'?x/y:x%y;}else if(code=='=')z=x==y?-1:0;else if(code==257)z=x!=y?-1:0;else if(code=='<')z=x<y?-1:0;else if(code=='>')z=x>y?-1:0;else if(code==258)z=x<=y?-1:0;else if(code==259)z=x>=y?-1:0;else if(code==261)z=x&&y?-1:0;else if(code==262)z=x||y?-1:0;else if(code==263)z=!!x!=!!y?-1:0;a.number=z;}
 return a;}
static int line_text(Basic *b,int line,char *out){if(line<0||line>=b->lines)return 0;const char *s=b->code+b->line[line];int n=0;while(*s&&*s!='\n'&&*s!='\r'){if(n==255)return 0;out[n++]=*s++;}out[n]=0;return 1;}
static int starts_line(Basic *b,int line,const char *keyword){char text[256];if(!line_text(b,line,text))return 0;Parser p={b,0,text,0};return word(&p,keyword);}
static int block_if(Basic *b,int line){char text[256];if(!line_text(b,line,text))return 0;Parser p={b,0,text,0};if(!word(&p,"If"))return 0;int quote=0;while(*p.p){if(*p.p=='"')quote=!quote;if(!quote){const char *save=p.p;if(word(&p,"Then")){spaces(&p);return !*p.p||*p.p=='\'';}p.p=save;}p.p++;}return 0;}
 static int matching(Basic *b,int line,const char *begin,const char *end,int direction){int depth=0;for(int i=line+direction;i>=0&&i<b->lines;i+=direction){if(starts_line(b,i,direction>0?begin:end)&&(!BasicEqual(direction>0?begin:end,"If")||block_if(b,i)))depth++;if(starts_line(b,i,direction>0?end:begin)&&(!BasicEqual(direction>0?end:begin,"If")||block_if(b,i))){if(!depth)return i;depth--;}}return -1;}
static int assign(Parser *p,const char *name,int index,const BasicValue *v){if(index>=0){int i=variable(p->b,name,0);if(i<0||index>=p->b->variable[i].array_size){fail(p,"Array index out of range");return 0;}p->b->variable[i].array[index]=numeric(p,v);return 1;}
 for(const char *s=name;*s;s++)if(*s=='.'){if(!p->host->set||p->host->set(name,v)<0)fail(p,"Invalid control property");return !p->b->error[0];}int i=variable(p->b,name,1);if(i<0){fail(p,"Variable limit");return 0;}BasicVariable *var=&p->b->variable[i];if(var->array_size){fail(p,"Array requires an index");return 0;}if(var->type==1||var->type==2||var->type==4){i32 n=numeric(p,v);if(var->type==1&&(n< -32768||n>32767)){fail(p,"Integer overflow");return 0;}var->value.string=0;var->value.number=var->type==4?(n?-1:0):n;}else if(var->type==3){var->value.string=1;BasicText(v,var->value.text);}else var->value=*v;return 1;}
static int procedure(Basic *b,const char *name){for(int i=0;i<b->procedures;i++)if(BasicEqual(b->procedure[i].name,name))return i;return -1;}
int BasicLoad(Basic *b,const char *code){memset(b,0,sizeof(*b));b->else_line=-1;if(strlen(code)>=BASIC_CODE){copy(b->error,"Code exceeds 8191 bytes");return S_LIMIT;}copy(b->code,code);b->line[0]=0;b->lines=1;for(u32 i=0;b->code[i];i++)if(b->code[i]=='\n'&&b->code[i+1]){if(b->lines==BASIC_LINES){copy(b->error,"Line limit 256");return S_LIMIT;}b->line[b->lines++]=(u16)(i+1);}
 for(int i=0;i<b->lines;i++){char text[256];if(!line_text(b,i,text)){copy(b->error,"Line limit 255 bytes");b->error_line=i+1;return S_LIMIT;}Parser p={b,0,text,0};b->pc=i;if(word(&p,"Function")){fail(&p,"User Function definitions are not supported yet");return S_INVALID;}if(word(&p,"Sub")){if(b->procedures==16){fail(&p,"Procedure limit 16");return S_LIMIT;}BasicProcedure *proc=&b->procedure[b->procedures];if(!identifier(&p,proc->name)||procedure(b,proc->name)>=0){fail(&p,"Invalid/duplicate Sub name");return S_INVALID;}spaces(&p);if(*p.p=='('){p.p++;spaces(&p);if(*p.p++!=')'){fail(&p,"Sub parameters are not supported yet");return S_INVALID;}}proc->first=i;proc->last=matching(b,i,"Sub","End Sub",1);if(proc->last<0){fail(&p,"Missing End Sub");return S_INVALID;}b->procedures++;i=proc->last;}}
 return 0;}
int BasicStart(Basic *b,const char *event){int n=procedure(b,event);if(n<0)return S_NOTFOUND;b->pc=b->procedure[n].first+1;b->end=b->procedure[n].last;b->running=1;b->loops=b->calls=0;b->else_line=-1;b->error[0]=0;return 0;}
static void execute(Parser *p);
static void if_false(Parser *p){Basic *b=p->b;int depth=0;for(int i=b->pc+1;i<b->lines;i++){if(block_if(b,i))depth++;if(starts_line(b,i,"End If")){if(!depth){b->pc=i;return;}depth--;}if(!depth&&(starts_line(b,i,"Else")||starts_line(b,i,"ElseIf"))){if(starts_line(b,i,"ElseIf")){b->else_line=i;b->pc=i-1;}else b->pc=i;return;}}fail(p,"Missing End If");}
static void execute(Parser *p){Basic *b=p->b;spaces(p);if(!*p->p||*p->p=='\''||word(p,"Rem"))return;
 if(word(p,"Dim")){char name[32];if(!identifier(p,name)){fail(p,"Expected variable name");return;}int i=variable(b,name,1);if(i<0){fail(p,"Variable limit");return;}BasicVariable *v=&b->variable[i];spaces(p);if(*p->p=='('){p->p++;BasicValue size=expression(p,1);i32 n=numeric(p,&size);spaces(p);if(*p->p!=')'||n<0||n>15){fail(p,"Array maximum index is 15");return;}p->p++;v->array_size=n+1;}if(word(p,"As")){if(word(p,"Integer"))v->type=1;else if(word(p,"Long"))v->type=2;else if(word(p,"String"))v->type=3;else if(word(p,"Boolean"))v->type=4;else if(word(p,"Variant"))v->type=0;else fail(p,"Unsupported type");}if(v->type==3){if(v->array_size)fail(p,"String arrays not supported");else BasicString(&v->value,"");}return;}
 if(word(p,"If")||word(p,"ElseIf")){int line=b->pc;BasicValue v=expression(p,1);if(!word(p,"Then")){fail(p,"Expected Then");return;}spaces(p);if(*p->p){if(numeric(p,&v))execute(p);else p->p+=strlen(p->p);return;}if(!numeric(p,&v))if_false(p);else b->else_line=-1;(void)line;return;}
 if(word(p,"Else")){int end=matching(b,b->pc,"If","End If",1);if(end<0)fail(p,"Missing End If");else b->pc=end;return;}
 if(word(p,"End If")||word(p,"End Select"))return;
 if(word(p,"For")){char name[32];if(!identifier(p,name)){fail(p,"Expected For variable");return;}spaces(p);if(*p->p++!='='){fail(p,"Expected =");return;}BasicValue start=expression(p,1);if(!word(p,"To")){fail(p,"Expected To");return;}BasicValue finish=expression(p,1),step={0};step.number=1;if(word(p,"Step"))step=expression(p,1);int index=variable(b,name,1);i32 a=numeric(p,&start),z=numeric(p,&finish),s=numeric(p,&step);if(index<0||!s||b->loops==8){fail(p,"Invalid For or loop limit");return;}assign(p,name,-1,&start);if((s>0&&a>z)||(s<0&&a<z)){int end=matching(b,b->pc,"For","Next",1);if(end<0)fail(p,"Missing Next");else b->pc=end;return;}b->loop[b->loops++]=(BasicLoop){index,b->pc,z,s};return;}
 if(word(p,"Next")){if(!b->loops){fail(p,"Next without For");return;}BasicLoop *l=&b->loop[b->loops-1];char name[32];if(identifier(p,name)&&!BasicEqual(name,b->variable[l->variable].name)){fail(p,"Next variable mismatch");return;}i32 n;if(__builtin_add_overflow(b->variable[l->variable].value.number,l->step,&n)){fail(p,"For overflow");return;}b->variable[l->variable].value.number=n;if(l->step>0?n<=l->end:n>=l->end)b->pc=l->line;else b->loops--;return;}
 if(word(p,"While")){BasicValue v=expression(p,1);if(!numeric(p,&v)){int end=matching(b,b->pc,"While","Wend",1);if(end<0)fail(p,"Missing Wend");else b->pc=end;}return;}
 if(word(p,"Wend")){int start=matching(b,b->pc,"While","Wend",-1);if(start<0)fail(p,"Wend without While");else b->pc=start-1;return;}
 if(word(p,"Do")){int until=word(p,"Until"),test=until||word(p,"While");if(test){BasicValue v=expression(p,1);if(!!numeric(p,&v)==until){int end=matching(b,b->pc,"Do","Loop",1);if(end<0)fail(p,"Missing Loop");else b->pc=end;}}return;}
 if(word(p,"Loop")){int until=word(p,"Until"),test=until||word(p,"While"),repeat=1;if(test){BasicValue v=expression(p,1);repeat=!!numeric(p,&v)!=until;}if(repeat){int start=matching(b,b->pc,"Do","Loop",-1);if(start<0)fail(p,"Loop without Do");else b->pc=start-1;}return;}
 if(word(p,"Select Case")){BasicValue value=expression(p,1);int depth=0;for(int i=b->pc+1;i<b->lines;i++){if(starts_line(b,i,"Select Case"))depth++;if(starts_line(b,i,"End Select")){if(!depth){b->pc=i;return;}depth--;}if(!depth&&starts_line(b,i,"Case")){char text[256];line_text(b,i,text);Parser q={b,p->host,text,0};word(&q,"Case");if(word(&q,"Else")){b->pc=i;return;}BasicValue c=expression(&q,1);char x[128],y[128];BasicText(&value,x);BasicText(&c,y);if(streq(x,y)){b->pc=i;return;}}}fail(p,"Missing End Select");return;}
 if(word(p,"Case")){int end=matching(b,b->pc,"Select Case","End Select",1);if(end<0)fail(p,"Missing End Select");else b->pc=end;return;}
 if(word(p,"Print")){BasicValue v=expression(p,1);char text[128];BasicText(&v,text);if(p->host->print)p->host->print(text);return;}
 if(word(p,"MsgBox")){BasicValue v=expression(p,1);char text[128],answer[128]={0};BasicText(&v,text);if(p->host->dialog)p->host->dialog(text,answer,0);return;}
 int write_file=word(p,"WriteFile"),write_config=!write_file&&word(p,"ConfigWrite");if(write_file||write_config){BasicValue path=expression(p,1);spaces(p);if(*p->p++!=','){fail(p,"Expected comma");return;}BasicValue data=expression(p,1);char target[128],text[128];BasicText(&path,target);BasicText(&data,text);if(write_config){if(strlen(target)>24){fail(p,"Config key too long");return;}for(u32 i=0;target[i];i++)if(!namechar(target[i])||target[i]=='.'){fail(p,"Invalid config key");return;}char key[32];copy(key,target);copy(target,"/home/user/.sino/config/");copy(target+strlen(target),key);}if(Write(target,text,strlen(text))<0)fail(p,"File/config write failed");return;}
 if(word(p,"Call")){char name[32];if(!identifier(p,name)){fail(p,"Expected Sub name");return;}int proc=procedure(b,name);spaces(p);if(*p->p=='('){p->p++;spaces(p);if(*p->p++!=')'){fail(p,"Sub parameters are not supported yet");return;}}if(proc<0||b->calls==8){fail(p,"Unknown Sub or call limit");return;}b->call[b->calls++]=(BasicCall){b->pc,b->end};b->pc=b->procedure[proc].first;b->end=b->procedure[proc].last;return;}
 if(word(p,"Exit Sub")||word(p,"End Sub")){b->pc=b->end;return;}if(word(p,"Stop")||word(p,"End")){b->running=0;return;}
 char name[32];word(p,"Let");if(!identifier(p,name)){fail(p,"Unsupported statement");return;}int index=-1;spaces(p);if(*p->p=='('){p->p++;BasicValue v=expression(p,1);index=numeric(p,&v);spaces(p);if(*p->p++!=')'||index<0){fail(p,"Invalid array index");return;}}spaces(p);if(*p->p++!='='){fail(p,"Expected assignment");return;}BasicValue v=expression(p,1);assign(p,name,index,&v);spaces(p);if(*p->p&&*p->p!='\'')fail(p,"Unexpected tokens after expression");}
int BasicStep(Basic *b,const BasicHost *host){if(!b->running)return 0;if(b->pc>=b->end){if(b->calls){BasicCall call=b->call[--b->calls];b->pc=call.pc+1;b->end=call.end;return 1;}b->running=0;return 0;}char text[256];if(!line_text(b,b->pc,text)){copy(b->error,"Invalid program line");b->error_line=b->pc+1;b->running=0;return S_INVALID;}Parser p={b,host,text,0};if(starts_line(b,b->pc,"ElseIf")&&b->else_line!=b->pc){int end=matching(b,b->pc,"If","End If",1);if(end<0)fail(&p,"Missing End If");else b->pc=end;}else{int pc=b->pc;execute(&p);spaces(&p);if(b->pc==pc&&*p.p&&*p.p!='\'')fail(&p,"Unexpected tokens after statement");}b->pc++;return b->error[0]?S_INVALID:b->running;}
